root<-normalizePath(commandArgs(TRUE)[1]);.libPaths(c(file.path(root,'Rlib'),.libPaths()));source(file.path(root,'code/common.R'));suppressPackageStartupMessages(library(celldex));options(timeout=900)
# Keep downloaded public reference cache isolated in this analysis, not the existing project libraries.
